<script setup lang="ts">
import {computed,ref,watch} from 'vue';
import {AlertCircle,LoaderCircle,ArrowRight,ChevronLeft,ChevronRight,Info,Search,Workflow} from 'lucide-vue-next';
type Item=Record<string,any>;
const props=defineProps<{report:Item;schema:string;busy:boolean;error?:string}>();
const emit=defineEmits<{query:[filters:{schema:string|null;search:string|null;offset:number}]}>();
const search=ref(props.report.search??'');const limit=ref(20);
const relationships=computed<Item[]>(()=>props.report.relationships??[]);
const visible=computed(()=>relationships.value.slice(0,limit.value));
function filter(){emit('query',{schema:props.schema.trim()||null,search:search.value.trim()||null,offset:0});}
function page(offset:number){emit('query',{schema:props.report.schema??null,search:props.report.search??null,offset});}
watch(()=>props.report,()=>{search.value=props.report.search??'';limit.value=20;});
</script>
<template>
 <section class="source-relationships" :aria-busy="busy" aria-label="Relacionamentos declarados da fonte" data-tour="credential-relationships">
  <div class="relationship-guidance"><Info :size="17"/><div><p>Vínculos declarados e visíveis para esta conexão. Confirme a regra de negócio antes de combinar tabelas.</p><details><summary>Como interpretar esta consulta</summary><p>{{report.scope_warning}}</p></details></div></div>
  <form class="relationship-search" @submit.prevent="filter"><label>Buscar por tabela ou relacionamento<div><Search :size="16"/><input v-model="search" maxlength="100" :disabled="busy" placeholder="Ex.: financeiro, pedido, atendimento…"></div></label><button class="secondary-button" :disabled="busy" type="submit">Buscar na fonte</button></form>
  <p v-if="busy" class="query-status" role="status"><LoaderCircle :size="15" class="spin"/>Consultando a fonte… O resultado anterior continua visível até a resposta.</p>
  <p v-if="error" class="form-error query-error" role="alert"><AlertCircle :size="16"/>{{error}}</p>
  <p class="relationship-scope">{{report.schema?'Schema consultado: '+report.schema:'Schemas disponíveis para a conexão'}}<span v-if="report.search"> · Busca: {{report.search}}</span></p>
  <nav v-if="report.offset>0||report.next_offset!==null" class="relationship-pagination" aria-label="Páginas de relacionamentos"><button type="button" class="secondary-button" :disabled="busy||report.offset===0" @click="page(Math.max(0,report.offset-report.page_size))"><ChevronLeft :size="15"/>Anterior</button><span>Página {{Math.floor(report.offset/report.page_size)+1}}</span><button type="button" class="secondary-button" :disabled="busy||report.next_offset===null" @click="page(report.next_offset)">Próxima<ChevronRight :size="15"/></button></nav>
  <p v-if="relationships.length" class="relationship-scope">Exibindo {{visible.length}} de {{relationships.length}} vínculos desta página.</p>
  <div v-if="relationships.length" class="relationship-list"><article v-for="link in visible" :key="link.id"><header><Workflow :size="16"/><strong>Vínculo declarado</strong><div class="relationship-badges"><span v-if="link.column_count_verified===false" class="relationship-badge attention">Cobertura a conferir</span><span v-else-if="!link.complete" class="relationship-badge attention">Campos incompletos</span><span v-if="link.enabled===false" class="relationship-badge attention">Desativado na fonte</span><span v-if="link.validated===false" class="relationship-badge attention">Não validado na fonte</span><span v-else class="relationship-badge">{{link.validated===true?'Validado na fonte':'Validação não informada'}}</span></div></header><div class="relationship-tables"><div><small>Esta tabela</small><strong>{{link.from.table}}</strong><small>{{link.from.schema}}</small></div><ArrowRight :size="17"/><div><small>Referência nesta tabela</small><strong>{{link.to.table}}</strong><small>{{link.to.schema}}</small></div></div><dl><div v-for="column in link.columns" :key="column.position"><dt>{{column.source}}</dt><dd><ArrowRight :size="12"/>{{column.target}}</dd></div></dl><p v-if="link.column_count_verified===false" class="relationship-incomplete">Este conector pode ocultar campos por permissão. O total de campos da chave não foi confirmado; os pares visíveis não devem ser usados como chave completa sem investigação.</p><p v-else-if="!link.complete" class="relationship-incomplete">Parte dos {{link.column_count}} campos está nesta página. Refine a busca pelo nome do vínculo para conferir todos os pares antes de combinar as tabelas.</p><p v-if="link.enabled===false&&link.validated===false" class="relationship-incomplete">Este vínculo também não está validado na fonte.</p><footer><span>{{link.name}}</span><small v-if="link.column_count_verified===false">{{link.columns.length}} {{link.columns.length===1?'campo visível':'campos visíveis'}}</small><small v-else>{{link.columns.length}} de {{link.column_count}} {{link.column_count===1?'campo':'campos'}}</small></footer></article></div>
  <button v-if="relationships.length>visible.length" class="text-button relationship-show-more" :disabled="busy" @click="limit+=20">Mostrar mais vínculos desta página · {{relationships.length-visible.length}} restantes</button>
  <p v-if="report.truncated" class="relationship-pagination-note">{{report.pagination_limit_reached?'O limite de paginação foi atingido; refine a busca para continuar.':'Há mais campos de relacionamentos na fonte. Continue a consulta ou refine a busca.'}} Os resultados refletem o momento de cada consulta.</p>
 </section>
</template>
<style scoped>
.query-status{display:flex;gap:8px;align-items:flex-start;font-size:11px;line-height:1.8;color:#466a9b;margin:12px 0}.query-status svg,.query-error svg{flex-shrink:0;margin-top:2px}.query-error{margin:12px 0;font-size:12px;line-height:1.8}
.source-relationships{margin-top:16px}.relationship-guidance{display:flex;gap:9px;padding:12px;background:#edf4ff;border:1px solid #d9e6fa;border-radius:8px;color:#45658e}.relationship-guidance>svg{flex-shrink:0;margin-top:2px}.relationship-guidance>div{min-width:0}.relationship-guidance details{margin-top:6px}.relationship-guidance summary{font-size:11px;color:#35649f;cursor:pointer;line-height:1.7}.relationship-guidance details p{margin-top:8px}.relationship-guidance p{font-size:12px;line-height:1.8;margin:0}.relationship-search{display:flex;gap:10px;align-items:flex-end;margin:16px 0 8px}.relationship-search label{flex:1;min-width:0;font-size:11px;color:#425f83}.relationship-search label>div{display:flex;align-items:center;gap:8px;background:white;border:1px solid #dbe5f3;border-radius:7px;padding:0 10px;margin-top:6px}.relationship-search input{min-width:0;width:100%;border:0;margin:0;background:transparent;box-shadow:none}.relationship-search button{min-height:41px;font-size:11px}.relationship-scope,.relationship-pagination-note{font-size:11px;line-height:1.8;color:#647c9c;margin:8px 0 14px}.relationship-list{display:grid;gap:12px}.relationship-list article{border:1px solid #dbe5f2;border-radius:9px;background:white;padding:14px;min-width:0}.relationship-list header{display:flex;align-items:center;gap:7px;flex-wrap:wrap;color:#426997}.relationship-list header>strong{font-size:11px}.relationship-badges{display:flex;flex-wrap:wrap;gap:6px;margin-left:auto}.relationship-badge{font-size:10px;padding:4px 7px;background:#edf3fb;color:#49678e;border-radius:5px}.relationship-badge.attention{background:#fff3df;color:#8b5a20}.relationship-tables{display:grid;grid-template-columns:minmax(0,1fr) 20px minmax(0,1fr);gap:10px;align-items:center;padding:15px 0;color:#7793b8}.relationship-tables>div{min-width:0}.relationship-tables strong{display:block;font-size:12px;overflow-wrap:anywhere;color:#284c79;margin:5px 0}.relationship-tables small{display:block;font-size:10px;color:#6b819e;overflow-wrap:anywhere}.relationship-list dl{margin:0;background:#f7faff;border-radius:6px;padding:4px 10px}.relationship-list dl>div{display:grid;grid-template-columns:minmax(0,1fr) minmax(0,1fr);gap:12px;padding:7px 0;border-bottom:1px solid #e7eef8}.relationship-list dl>div:last-child{border-bottom:0}.relationship-list dt,.relationship-list dd{font-size:11px;overflow-wrap:anywhere;color:#466385;margin:0;line-height:1.8}.relationship-list dd{display:flex;gap:9px;align-items:flex-start}.relationship-list dd svg{margin-top:4px}.relationship-incomplete{font-size:11px;color:#8a5d29;line-height:1.8;margin:10px 0}.relationship-list footer{display:flex;justify-content:space-between;gap:14px;margin-top:10px;font-size:10px;color:#7186a2;overflow-wrap:anywhere}.relationship-list footer>span{min-width:0}.relationship-list footer small{flex-shrink:0}.relationship-show-more{margin:12px 0;font-size:12px}.relationship-pagination{display:flex;gap:10px;justify-content:space-between;align-items:center;margin-top:15px}.relationship-pagination span{font-size:11px;color:#5d7495}.relationship-pagination .secondary-button{font-size:11px}.source-relationships button:focus-visible{outline:2px solid #0861ee;outline-offset:3px}@media(max-width:600px){.relationship-search{align-items:stretch;flex-direction:column}.relationship-search button{align-self:flex-end}.relationship-list article{padding:11px}.relationship-badges{margin-left:0;width:100%}.relationship-tables{gap:7px;grid-template-columns:minmax(0,1fr) 16px minmax(0,1fr)}.relationship-list dl{padding:4px 8px}}
</style>
